INSERT INTO `products` VALUES ('11111111-0000-0002-0001-000000000001','11111111-0000-0000-0000-000000000001','11111111-0000-0000-0001-000000000001','Pure Desi Ghee Motichoor Laddu (500g)',NULL,NULL,'Melt-in-mouth golden pearls of gram flour sweetened with saffron-infused syrup.',320.00,33,5,'/sweets/motichoor-laddu.svg','AVAILABLE',1,'2026-10-12 10:41:35','2026-10-13 11:40:30'),('11111111-0000-0002-0001-000000000002','11111111-0000-0000-0000-000000000001','11111111-0000-0000-0001-000000000001','Kesar Khoya Peda (400g)',NULL,NULL,'Rich slow-cooked condensed milk fudge flavored with pure Kashmiri saffron.',290.00,27,5,'/sweets/motichoor-laddu.svg','AVAILABLE',1,'2026-10-12 10:41:35','2026-10-12 13:32:23'),('11111111-0000-0002-0001-000000000003','11111111-0000-0000-0000-000000000001','11111111-0000-0000-0001-000000000001','Besan Laddu with Dry Fruits (500g)',NULL,NULL,'Roasted gram flour spheres enriched with pure desi ghee, almonds, and cashews.',340.00,40,5,'/sweets/motichoor-laddu.svg','AVAILABLE',1,'2026-10-12 10:41:35','2026-10-12 11:59:55'),('11111111-0000-0002-0001-000000000004','11111111-0000-0000-0000-000000000001','11111111-0000-0000-0001-000000000002','Diamond Kaju Katli (500g)',NULL,NULL,'Classic diamond-shaped cashew fudge with delicate edible silver foil.',490.00,46,5,'/sweets/kaju-katli.svg','AVAILABLE',1,'2026-10-12 10:41:35','2026-10-13 12:39:36'),('11111111-0000-0002-0001-000000000005','11111111-0000-0000-0000-000000000001','11111111-0000-0000-0001-000000000002','Pista Katli Royal Box (400g)',NULL,NULL,'Fragrant emerald pistachio fudge crafted with hand-selected Iranian pistachios.',580.00,25,5,'/sweets/kaju-katli.svg','AVAILABLE',1,'2026-10-12 10:41:35','2026-10-12 11:59:55'),('2000363c-7302-4ddc-8a29-24ea4b3a8332','daecef5a-1198-4dc3-800d-f15a96e7986b',NULL,'cake','198','2',NULL,400.00,2,5,'/uploads/products/products_1791894908288_e8b74d9ac7b1.jpg','AVAILABLE',1,'2026-10-13 12:35:10','2026-10-13 12:35:10'),('22222222-0000-0002-0001-000000000001','22