INSERT INTO `roles` VALUES ('00000000-0000-0000-0000-000000000001','SUPER_ADMIN','Global super administrator with full system-wide access and staff management.','2026-10-12 08:38:29','2026-10-12 08:38:29'),('00000000-0000-0000-0000-000000000002','ADMIN','Platform operations administrator managing sellers, sweet shop compliance, and approvals.','2026-10-12 08:38:29','2026-10-12 08:38:29'),('00000000-0000-0000-0000-000000000003','ACCOUNTANT','Financial management, vendor payouts, settlements, and tax accounting.','2026-10-12 08:38:29','2026-10-12 08:38:29'),('00000000-0000-0000-0000-000000000004','SELLER','Sweet shop vendor/store owner account managing catalog, orders, and branch operations.','2026-10-12 08:38:29','2026-10-12 08:38:29'),('00000000-0000-0000-0000-000000000005','CUSTOMER_CARE','Customer support agent managing inquiries, order complaints, and ticket resolutions.','2026-10-12 08:38:29','2026-10-12 08:38:29'),('00000000-0000-0000-0000-000000000006','CUSTOMER','End-user customer purchasing sweets and tracking deliveries under a seller store.','2026-10-12 08:38:29','2026-10-12 08:38:29');
