DROP TABLE IF EXISTS `seller_verifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `seller_verifications` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `seller_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submission_version` int NOT NULL DEFAULT '1',
  `document_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'KYC_BUNDLE',
  `msme_certificate` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_document` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fssai_license` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `other_documents` text COLLATE utf8mb4_unicode_ci,
  `verification_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `is_current` tinyint(1) NOT NULL DEFAULT '1',
  `current_flag` tinyint GENERATED ALWAYS AS (if((`is_current` = 1),1,NULL)) VIRTUAL,
  `reviewed_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_seller_verification_active_current` (`seller_id`,`document_type`,`current_flag`),
  KEY `idx_seller_verifications_seller` (`seller_id`),
  KEY `idx_seller_verifications_status` (`verification_status`),
  CONSTRAINT `fk_seller_verifications_seller` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_seller_verifications_status` CHECK ((`verification_status` in (_utf8mb4'PENDING',_utf8mb4'UNDER_REVIEW',_utf8mb4'APPROVED',_utf8mb4'REJECTED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

