DROP TABLE IF EXISTS `sellers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sellers` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `business_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `legal_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `owner_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROPRIETORSHIP',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shop_address` text COLLATE utf8mb4_unicode_ci,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pincode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gstin` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `profile_photo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_APPROVAL',
  `verification_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_login_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sellers_email` (`email`),
  UNIQUE KEY `uq_sellers_gstin` (`gstin`),
  KEY `idx_sellers_account_status` (`account_status`),
  KEY `idx_sellers_verification_status` (`verification_status`),
  KEY `idx_sellers_created_by` (`created_by`),
  CONSTRAINT `chk_sellers_account_status` CHECK ((`account_status` in (_utf8mb4'PENDING_APPROVAL',_utf8mb4'ACTIVE',_utf8mb4'SUSPENDED',_utf8mb4'TERMINATED'))),
  CONSTRAINT `chk_sellers_business_type` CHECK ((`business_type` in (_utf8mb4'PROPRIETORSHIP',_utf8mb4'PARTNERSHIP',_utf8mb4'PVT_LTD',_utf8mb4'LLP',_utf8mb4'PUBLIC_LTD',_utf8mb4'OTHER'))),
  CONSTRAINT `chk_sellers_created_by_type` CHECK (((`created_by_type` in (_utf8mb4'SUPER_ADMIN',_utf8mb4'ADMIN')) or (`created_by_type` is null))),
  CONSTRAINT `chk_sellers_verification_status` CHECK ((`verification_status` in (_utf8mb4'PENDING',_utf8mb4'UNDER_REVIEW',_utf8mb4'APPROVED',_utf8mb4'REJECTED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
