--
-- Table structure for table `vendor_settlements`
--

DROP TABLE IF EXISTS `vendor_settlements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_settlements` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `order_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `seller_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gross_order_amount` decimal(10,2) NOT NULL,
  `commission_rate` decimal(5,2) NOT NULL DEFAULT '10.00',
  `platform_commission` decimal(10,2) NOT NULL,
  `packaging_reimbursement` decimal(10,2) NOT NULL DEFAULT '0.00',
  `delivery_fee_retained` decimal(10,2) NOT NULL DEFAULT '0.00',
  `gst_retained` decimal(10,2) NOT NULL DEFAULT '0.00',
  `net_seller_payout` decimal(10,2) NOT NULL,
  `settlement_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_PAYOUT',
  `payout_batch_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payout_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_settlements_order_id` (`order_id`),
  KEY `idx_settlements_seller_id` (`seller_id`),
  KEY `idx_settlements_status` (`settlement_status`),
  KEY `fk_settlements_payment` (`payment_id`),
  CONSTRAINT `fk_settlements_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_settlements_payment` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_settlements_seller` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_settlements_status` CHECK ((`settlement_status` in (_utf8mb4'PENDING_PAYOUT',_utf8mb4'PROCESSING',_utf8mb4'SETTLED',_utf8mb4'ON_HOLD',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

